'use strict';
const $=s=>document.querySelector(s), colors=['#f2ef24','#ff427f','#244bff','#19da64','#ff572a','#9655ff'];
let db,books=[],page=0,view='shelf',selected=null,statusTimer,coverURL;
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function message(text,sticky=false){clearTimeout(statusTimer);$('#status').textContent=text;$('#status').hidden=false;if(!sticky)statusTimer=setTimeout(()=>$('#status').hidden=true,5500)}
function transaction(mode,fn){return new Promise((resolve,reject)=>{const tx=db.transaction('books',mode);let result;try{result=fn(tx.objectStore('books'))}catch(e){reject(e);return}tx.oncomplete=()=>resolve(result?.result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('Storage operation aborted'));})}
async function persist(book){await transaction('readwrite',s=>s.put(book));}
const SHELF_CAPACITY=16;
function pages(){return Array.from({length:Math.max(1,Math.ceil(books.length/SHELF_CAPACITY))},(_,i)=>books.slice(i*SHELF_CAPACITY,(i+1)*SHELF_CAPACITY));}
const clamp=(value,min,max,fallback)=>Number.isFinite(Number(value))?Math.min(max,Math.max(min,Number(value))):fallback;
function defaultAppearance(b){
  // Legacy records keep their original proportions, color and typography.
  return {orientation:({'demo-dream':'left','demo-sherlock':'horizontal'})[b.id]||'upright',thickness:clamp(b.width,32,140,70),height:clamp(b.height,180,340,280),tilt:6,color:/^#[0-9a-f]{6}$/i.test(b.color)?b.color:'#244bff',typography:['sans','serif','italic'].includes(b.type)?b.type:'sans'};
}
function appearanceOf(b){const fallback=defaultAppearance(b),a=b.appearance||{};return {orientation:['upright','left','right','horizontal'].includes(a.orientation)?a.orientation:fallback.orientation,thickness:clamp(a.thickness,32,140,fallback.thickness),height:clamp(a.height,180,340,fallback.height),tilt:clamp(a.tilt,2,12,6),color:/^#[0-9a-f]{6}$/i.test(a.color)?a.color:fallback.color,typography:['sans','serif','italic'].includes(a.typography)?a.typography:fallback.typography};}
function bookMarkup(b,index,preview=false){const a=appearanceOf(b),horizontal=a.orientation==='horizontal',angle=a.orientation==='left'?-a.tilt:a.orientation==='right'?a.tilt:0;
const radians=Math.abs(angle)*Math.PI/180,boxWidth=horizontal?a.height:Math.ceil(a.thickness*Math.cos(radians)+a.height*Math.sin(radians)),boxHeight=horizontal?a.thickness:Math.ceil(a.height*Math.cos(radians)+a.thickness*Math.sin(radians));
return `<div class="book-slot ${horizontal?'landscape':''}" style="--slot-width:${boxWidth}px;--slot-height:${boxHeight}px"><${preview?'div':'button'} class="book ${a.typography} ${horizontal?'horizontal':''} ${!horizontal&&a.thickness<55?'thin':''}" ${preview?'':`data-id="${escapeHTML(b.id)}"`} aria-label="${escapeHTML(b.title+' — '+b.author)}" title="${escapeHTML(b.title+' — '+b.author)}" style="--color:${a.color};--ink:${ink(a.color)};--width:${horizontal?a.height:a.thickness}px;--height:${horizontal?a.thickness:a.height}px;--angle:${angle}deg"><span class="spine-title">${escapeHTML(b.title)}</span><span class="spine-author">${escapeHTML(b.author)}</span><span class="spine-number">${String(index+1).padStart(2,'0')}</span><span class="spine-symbol">◇</span></${preview?'div':'button'}></div>`;}
function shelfMarkup(row){let html='';for(let i=0;i<row.length;i++){const b=row[i];if(appearanceOf(b).orientation==='horizontal'){let stack='';let count=0;while(i<row.length&&appearanceOf(row[i]).orientation==='horizontal'&&count<3){stack+=bookMarkup(row[i],books.indexOf(row[i]));i++;count++;}i--;html+=`<div class="book-stack">${stack}</div>`;}else html+=bookMarkup(b,books.indexOf(b));}return html;}
function ink(hex){const n=parseInt(hex.slice(1),16),r=n>>16,g=n>>8&255,b=n&255;return .299*r+.587*g+.114*b>150?'#101010':'#fff'}
function render(){const all=pages();page=Math.min(page,all.length-1);const row=all[page];$('#books').className='books'+(view==='list'?' list':'');$('#books').innerHTML=(view==='list'?row.map(b=>bookMarkup(b,books.indexOf(b))).join(''):shelfMarkup(row))+`<button class="book empty import" style="--height:225px;--width:65px" aria-label="Import an EPUB"><span class="plus">＋</span><span class="spine-title">YOUR NEXT STORY</span></button>`;
$('#count').textContent=String(books.length).padStart(2,'0');$('#pageCount').textContent=`${String(page+1).padStart(2,'0')} / ${String(all.length).padStart(2,'0')}`;$('#shelfLabel').textContent=`SHELF ${String(page+1).padStart(2,'0')} / ${page===0?'THE BEGINNING':'MORE WORLDS'}`;$('#previous').disabled=page===0;$('#next').disabled=page===all.length-1;$('#shelfCaption').textContent=books.some(b=>!b.demo)?'A growing collection of your own.':'A few worlds to get you started.';$('#spineView').classList.toggle('active',view==='shelf');$('#listView').classList.toggle('active',view==='list');}
async function start(){try{db=await new Promise((resolve,reject)=>{const r=indexedDB.open('personal-reading-workspace',1);r.onupgradeneeded=()=>r.result.createObjectStore('books',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.onblocked=()=>message('Close other tabs of this app to enable library storage.',true)});books=await transaction('readonly',s=>s.getAll());if(!books.length&&!localStorage.getItem('prw-initialized')){const demos=[{id:'demo-alice',title:'Alice in Wonderland',author:'Lewis Carroll',color:'#f2ef24',width:115,height:294,type:'serif',excerpt:'Alice was beginning to get very tired of sitting by her sister on the bank, and of having nothing to do: once or twice she had peeped into the book her sister was reading, but it had no pictures or conversations in it, “and what is the use of a book,” thought Alice, “without pictures or conversations?”'},{id:'demo-dream',title:'Những miền tưởng tượng',author:'Personal Reading Workspace',color:'#ff427f',width:91,height:265,type:'sans',excerpt:'Buổi sáng, Linh tìm thấy một cuốn sách nằm trên bậc cửa. Không có tên tác giả, chỉ có một dòng chữ màu xanh: “Mỗi câu chuyện bắt đầu khi bạn mở trang đầu tiên.” Cô mở sách. Trong khoảng lặng giữa hai dòng chữ, một thành phố dần hiện ra.'},{id:'demo-sherlock',title:'A Study in Scarlet',author:'Arthur Conan Doyle',color:'#244bff',width:126,height:313,type:'italic',excerpt:'In the year 1878 I took my degree of Doctor of Medicine of the University of London, and proceeded to Netley to go through the course prescribed for surgeons in the army. Having completed my studies there, I was duly attached to the Fifth Northumberland Fusiliers as Assistant Surgeon.'}].map(b=>({...b,demo:true,createdAt:Date.now()}));await transaction('readwrite',s=>{demos.forEach(b=>s.put(b))});books=demos;localStorage.setItem('prw-initialized','1')}books.sort((a,b)=>a.createdAt-b.createdAt);render()}catch(e){message('Library storage is unavailable. Enable browser storage and reload. No files will be imported until storage is available.',true);document.body.classList.add('busy')}}
function openBook(id){selected=books.find(b=>b.id===id);if(!selected)return;const b=selected;if(coverURL)URL.revokeObjectURL(coverURL);coverURL=b.cover?URL.createObjectURL(b.cover):null;$('#detailBody').innerHTML=(coverURL?`<img src="${coverURL}" alt="Book cover">`:'')+`<span class="demo">${b.demo?'DEMONSTRATION · SAMPLE EXCERPT':'IMPORTED EPUB · SAVED LOCALLY'}</span><h2>${escapeHTML(b.title)}</h2><p>${escapeHTML(b.author)}${b.file?` · ${(b.file.size/1024/1024).toFixed(2)} MB`:''}</p>`+(b.demo?`<p class="demo-excerpt">${escapeHTML(b.excerpt)}</p>`:'<p>Your original EPUB and available cover are stored in your library. Reader functionality arrives in Phase 2.</p>');const f=$('#editForm');f.elements.title.value=b.title;f.elements.author.value=b.author;setAppearanceForm(appearanceOf(b));updatePreview();$('#detail').showModal()}
function xml(text){const doc=new DOMParser().parseFromString(text,'application/xml');if(doc.querySelector('parsererror'))throw new Error('This EPUB contains invalid XML metadata.');return doc}
function localElement(doc,name){return [...doc.getElementsByTagName('*')].find(e=>e.localName===name)}
function resolvePath(base,relative){const url=new URL(relative,'https://epub.local/'+base);if(url.origin!=='https://epub.local')throw new Error('External EPUB file references are not supported.');return decodeURIComponent(url.pathname.slice(1))}
async function importFile(file){if(!db)return;if(!file.name.toLowerCase().endsWith('.epub'))return message('Please choose a DRM-free .epub file.');if(file.size>50*1024*1024)return message('Please choose an EPUB smaller than 50 MB.');document.body.classList.add('busy');message('Importing EPUB…',true);try{const zip=await JSZip.loadAsync(file);if(Object.keys(zip.files).length>10000)throw new Error('This EPUB contains too many files.');if(!zip.file('mimetype')||(await zip.file('mimetype').async('string')).trim()!=='application/epub+zip')throw new Error('This file is not a valid EPUB archive.');const entry=zip.file('META-INF/container.xml');if(!entry)throw new Error('EPUB container metadata is missing.');const container=xml(await entry.async('string')),root=localElement(container,'rootfile')?.getAttribute('full-path');if(!root||!zip.file(root))throw new Error('EPUB package metadata is missing.');const packageDoc=xml(await zip.file(root).async('string'));if(!localElement(packageDoc,'spine'))throw new Error('The EPUB has no reading spine.');const encrypted=zip.file('META-INF/encryption.xml');if(encrypted){const enc=xml(await encrypted.async('string'));if([...enc.getElementsByTagName('*')].some(e=>e.localName==='EncryptionMethod'&&!/idpf.org\/2008\/embedding|microsoft.com\/DRM\/2004\/07\/Epub#font/.test(e.getAttribute('Algorithm')||'')))throw new Error('This EPUB contains encrypted content. Please import a DRM-free copy.');}
const title=localElement(packageDoc,'title')?.textContent.trim()||file.name.replace(/\.epub$/i,''),author=localElement(packageDoc,'creator')?.textContent.trim()||'Unknown author';const items=[...packageDoc.getElementsByTagName('*')].filter(e=>e.localName==='item'),coverId=[...packageDoc.getElementsByTagName('*')].find(e=>e.localName==='meta'&&e.getAttribute('name')==='cover')?.getAttribute('content'),coverItem=items.find(e=>(e.getAttribute('properties')||'').split(/\s+/).includes('cover-image'))||items.find(e=>e.getAttribute('id')===coverId);let cover=null;if(coverItem&&/^image\/(jpeg|png|gif|webp)$/.test(coverItem.getAttribute('media-type')||'')){const cf=zip.file(resolvePath(root,coverItem.getAttribute('href')));if(cf){const data=await cf.async('uint8array');if(data.length<8*1024*1024)cover=new Blob([data],{type:coverItem.getAttribute('media-type')})}}
const b={id:crypto.randomUUID(),title,author,color:colors[books.length%colors.length],type:'sans',width:[38,55,75,100,135][books.length%5],height:[220,280,330][books.length%3],file,cover,packagePath:root,createdAt:Date.now(),demo:false};b.appearance={...defaultAppearance(b),orientation:['upright','upright','left','right','horizontal','horizontal'][books.length%6]};b.appearanceDefaults={...b.appearance};await persist(b);books.push(b);page=pages().length-1;render();message('EPUB imported and saved on this device.');openBook(b.id)}catch(e){message(e.message||'Import failed. Your existing library is unchanged.',true)}finally{document.body.classList.remove('busy');$('#file').value=''}}
document.addEventListener('click',e=>{if(e.target.closest('.import'))$('#file').click();const book=e.target.closest('[data-id]');if(book)openBook(book.dataset.id);if(e.target.closest('.close'))e.target.closest('dialog').close()});$('#file').onchange=()=>{if($('#file').files[0])importFile($('#file').files[0])};$('#spineView').onclick=()=>{view='shelf';render()};$('#listView').onclick=()=>{view='list';render()};$('#previous').onclick=()=>{page--;render();$('#books').scrollLeft=0};$('#next').onclick=()=>{page++;render();$('#books').scrollLeft=0};let wheelAt=0;
$('#books').addEventListener('wheel',e=>{if(e.shiftKey&&Math.abs(e.deltaX)>25&&Date.now()-wheelAt>450){e.preventDefault();page=Math.min(pages().length-1,Math.max(0,page+Math.sign(e.deltaX)));render();$('#books').scrollLeft=0;wheelAt=Date.now()}},{passive:false});
$('#libraryNav').onclick=$('.brand').onclick=e=>{e.preventDefault();document.querySelectorAll('dialog[open]').forEach(d=>d.close());page=0;render();scrollTo({top:0,behavior:'smooth'})};$('#aboutNav').onclick=()=>$('#about').showModal();
$('#editForm').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;const title=f.elements.title.value.trim();if(!title)return message('Please enter a book title.');const updated={...selected,title,author:f.elements.author.value.trim()||'Unknown author',color:f.elements.color.value,type:f.elements.type.value,appearance:appearanceFromForm(),appearanceDefaults:selected.appearanceDefaults||defaultAppearance(selected)};try{await persist(updated);books=books.map(b=>b.id===updated.id?updated:b);$('#detail').close();render();message('Book details saved.')}catch{message('Could not save changes. Your original book remains unchanged.',true)}};
$('#delete').onclick=async()=>{if(!confirm(`Delete “${selected.title}” and its local EPUB? Export a backup first if you need a copy.`))return;try{await transaction('readwrite',s=>s.delete(selected.id));books=books.filter(b=>b.id!==selected.id);$('#detail').close();render();message('Book deleted.')}catch{message('Could not delete the book. Please try again.',true)}};
$('#backup').onclick=async()=>{try{message('Preparing your backup…',true);const zip=new JSZip();const metadata=books.map(({file,cover,...b})=>b);for(const b of books){if(b.file)zip.file(`books/${b.id}.epub`,b.file);if(b.cover)zip.file(`covers/${b.id}`,b.cover)}zip.file('library.json',JSON.stringify({version:1,exportedAt:new Date().toISOString(),books:metadata},null,2));const blob=await zip.generateAsync({type:'blob'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='personal-reading-library.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);message('Backup exported. EPUBs can be re-imported; metadata restoration is not yet available.')}catch{message('Backup failed. Please try again.',true)}};
function setAppearanceForm(a){const f=$('#editForm');f.elements.color.value=a.color;f.elements.type.value=a.typography;f.elements.thickness.value=a.thickness;f.elements.height.value=a.height;f.elements.orientation.value=a.orientation;f.elements.tilt.value=a.tilt;}
function appearanceFromForm(){const f=$('#editForm');return {color:f.elements.color.value,typography:f.elements.type.value,thickness:Number(f.elements.thickness.value),height:Number(f.elements.height.value),orientation:f.elements.orientation.value,tilt:Number(f.elements.tilt.value)};}
function updatePreview(){if(!selected)return;const f=$('#editForm'),a=appearanceFromForm();$('#thicknessValue').textContent=a.thickness+' px';$('#heightValue').textContent=a.height+' px';$('#tiltValue').textContent=a.tilt+'°';$('#tiltControl').hidden=!['left','right'].includes(a.orientation);f.elements.tilt.disabled=$('#tiltControl').hidden;$('#appearancePreview').innerHTML=bookMarkup({...selected,title:f.elements.title.value,author:f.elements.author.value,appearance:a},books.indexOf(selected),true);}
$('#editForm').addEventListener('input',updatePreview);
$('#editForm').addEventListener('change',updatePreview);
$('#resetAppearance').onclick=()=>{setAppearanceForm(selected.appearanceDefaults||defaultAppearance(selected));updatePreview()};
start();
